cards.example:
upstream app { server 127.0.0.1:8000; keepalive 32; }

server {
  listen 443 ssl http2;
  server_name api.example.com;
  location / {
    proxy_pass http://app;
    proxy_set_header Host $host;
    proxy_set_header X-Real-IP $remote_addr;
    proxy_set_header X-Forwarded-Proto $scheme;
  }
}

location ~* \.(js|css|woff2|png)$ {
  add_header Cache-Control 'public, max-age=31536000, immutable';
}
location = /index.html {
  add_header Cache-Control 'no-cache';
}

limit_req_zone $binary_remote_addr zone=login:10m rate=5r/m;

location /api/login {
  limit_req zone=login burst=5 nodelay;
  proxy_pass http://app;
}

log_format main '$remote_addr $status $request_time $upstream_response_time '
                '$upstream_status "$request" rid=$request_id';
access_log /var/log/nginx/access.log main;
proxy_set_header X-Request-Id $request_id;

ssl_protocols TLSv1.2 TLSv1.3;
ssl_prefer_server_ciphers off;
ssl_session_cache shared:SSL:10m;
add_header Strict-Transport-Security 'max-age=31536000; includeSubDomains' always;

upstream app {
  least_conn;
  server 10.0.1.10:8000 max_fails=3 fail_timeout=10s;
  server 10.0.1.11:8000 max_fails=3 fail_timeout=10s;
  server 10.0.1.12:8000 backup;
}

add_header X-Frame-Options SAMEORIGIN always;
add_header X-Content-Type-Options nosniff always;
add_header Referrer-Policy strict-origin-when-cross-origin always;
add_header Content-Security-Policy "default-src 'self'" always;

location /ws {
  proxy_http_version 1.1;
  proxy_set_header Upgrade $http_upgrade;
  proxy_set_header Connection 'upgrade';
  proxy_read_timeout 3600s;
  proxy_buffering off;
}

location /api/ { proxy_pass http://app; }
location / {
  root /var/www/spa;
  try_files $uri $uri/ /index.html;
}

gzip on;
gzip_types text/css application/javascript application/json image/svg+xml;
gzip_min_length 1024;
gzip_comp_level 5;
